function cancelFade(media){const f=fadeFrames.get(media);if(f){cancelAnimationFrame(f);fadeFrames.delete(media)}}
function fade(media,target,duration=380){if(!media)return;cancelFade(media);target=clamp(target,0,.86);const start=clamp(media.volume),began=performance.now();if(target>0&&media.paused&&!document.hidden&&!backgroundPaused)media.play().catch(()=>{});const step=now=>{if(document.hidden||backgroundPaused){media.pause();fadeFrames.delete(media);return}const q=clamp((now-began)/Math.max(1,duration)),smooth=q*q*(3-2*q);media.volume=start+(target-start)*smooth;if(q<1)fadeFrames.set(media,requestAnimationFrame(step));else{fadeFrames.delete(media);if(target===0)media.pause()}};fadeFrames.set(media,requestAnimationFrame(step))}
function media(id){return $("#"+id)}
function playOne(id,mult=.5){const a=media(id);if(!a||!soundOn())return;try{a.currentTime=0;a.volume=clamp(sfxLevel()*mult,0,.72);a.play().catch(()=>{})}catch(_){} }

class CrossfadeLoop{
 constructor(a,b,overlap=2.2){this.a=a;this.b=b;this.active=a;this.other=b;this.overlap=overlap;this.target=0;this.running=false;this.timer=0;this.crossing=false}
 setTarget(v){this.target=clamp(v,0,.72);if(this.running&&!this.crossing&&this.active)fade(this.active,this.target,260)}
 start(v){this.target=clamp(v,0,.72);if(this.running){this.setTarget(this.target);return}this.running=true;this.crossing=false;const a=this.active;if(!a)return;try{if(!Number.isFinite(a.currentTime)||a.currentTime<0)a.currentTime=0;a.volume=0;if(!document.hidden&&!backgroundPaused)a.play().catch(()=>{});fade(a,this.target,520)}catch(_){}this.timer=setInterval(()=>this.tick(),140)}
 tick(){if(!this.running||document.hidden||backgroundPaused||this.crossing)return;const a=this.active,b=this.other;if(!a||!b||!Number.isFinite(a.duration)||a.duration<=this.overlap+1)return;if(a.currentTime<a.duration-this.overlap)return;this.crossing=true;try{b.currentTime=0;b.volume=0;b.play().catch(()=>{})}catch(_){};const started=performance.now(),dur=this.overlap*1000,target=this.target;const step=now=>{if(!this.running||document.hidden||backgroundPaused){a.pause();b.pause();this.crossing=false;return}const q=clamp((now-started)/dur),smooth=q*q*(3-2*q);a.volume=target*(1-smooth);b.volume=target*smooth;if(q<1)requestAnimationFrame(step);else{try{a.pause();a.currentTime=0}catch(_){}this.active=b;this.other=a;this.crossing=false}};requestAnimationFrame(step)}
 pause(){[this.a,this.b].forEach(x=>x?.pause())}
 resume(){if(!this.running||document.hidden)return;const a=this.active;if(a&&a.paused){a.volume=this.target;a.play().catch(()=>{})}}
 stop(reset=false){this.running=false;this.crossing=false;clearInterval(this.timer);this.timer=0;[this.a,this.b].forEach(x=>{cancelFade(x);try{x.pause();if(reset)x.currentTime=0;x.volume=0}catch(_){}});this.active=this.a;this.other=this.b}
}
let loopA=null,loopB=null;
function ensureLoopers(){if(loopA)return;loopA=new CrossfadeLoop(media("ch5P2MusicA1"),media("ch5P2MusicA2"),2.4);loopB=new CrossfadeLoop(media("ch5P2MusicB1"),media("ch5P2MusicB2"),2.6)}
function scoreMode(){const p=phaseState();return p?.identityConfirmed||p?.attributionComplete||p?.narinContactStarted?"b":"a"}
function scoreTarget(){if(!isP2()||!soundOn())return 0;let duck=1;if(dialogueActive)duck*=.62;if(miniOpen||narinOpen)duck*=.70;return clamp(musicLevel()*.42*duck,0,.44)}
function roomTarget(){return isP2()&&soundOn()?clamp(sfxLevel()*.075,0,.095):0}
function syncAudio(immediate=false){
 ensureLoopers();if(document.hidden||backgroundPaused){loopA.pause();loopB.pause();media("ch5P2RoomTone")?.pause();return}
 const target=scoreTarget(),mode=scoreMode();
 if(target<=0){loopA.setTarget(0);loopB.setTarget(0);loopA.pause();loopB.pause()}
 else if(mode==="a"){loopB.stop(false);loopA.start(target);loopA.setTarget(target)}else{loopA.stop(false);loopB.start(target);loopB.setTarget(target)}
 const room=media("ch5P2RoomTone");if(room){room.volume=roomTarget();if(room.volume>0&&room.paused)room.play().catch(()=>{});if(room.volume===0)room.pause()}
}
function stopAudio(reset=false){ensureLoopers();loopA.stop(reset);loopB.stop(reset);["ch5P2RoomTone","ch5P2Click1","ch5P2Click2","ch5P2Keys1","ch5P2Keys2","ch5P2Access","ch5P2Tick","ch5P2Reject","ch5P2Reveal","ch5P2NarinCue"].forEach(id=>{const a=media(id);if(!a)return;try{a.pause();if(reset)a.currentTime=0}catch(_){}})}
function stopForeignMedia(){try{window.LastWitnessChapter5Phase1?.stopAudio?.(true)}catch(_){};["LastWitnessChapter4Phase8","LastWitnessChapter4Phase7","LastWitnessChapter4Phase6","LastWitnessChapter4Phase5","LastWitnessChapter4Phase4","LastWitnessChapter4Phase3","LastWitnessChapter4Phase2","LastWitnessChapter4Phase1"].forEach(name=>{try{window[name]?.stopAudio?.(true)}catch(_){}});try{typeof stopLoops==="function"&&stopLoops()}catch(_){} }
function pauseForBackground(){if(backgroundPaused||!isP2())return;backgroundPaused=true;ensureLoopers();backgroundSnapshot={mode:scoreMode(),room:Boolean(media("ch5P2RoomTone")&&!media("ch5P2RoomTone").paused)};loopA.pause();loopB.pause();media("ch5P2RoomTone")?.pause()}
function resumeForeground(){if(!backgroundPaused||document.hidden)return;backgroundPaused=false;const snap=backgroundSnapshot;backgroundSnapshot=null;if(!isP2())return;syncAudio(true);if(snap?.room&&media("ch5P2RoomTone"))media("ch5P2RoomTone").play().catch(()=>{})}

