 p.attributionComplete=true;p.narinActive=true;p.stage="narin-lead";const s=gs();s.flags.ch5_p2_narin_active=true;s.flags.ch5_p2_attribution_boundary_preserved=true;unlockNarin();setProgress(82);save("ch5_p2_attribution_boundary");playOne("ch5P2Access",.42);try{window.LastWitnessHiddenCase?.recompute?.()}catch(_){};reconStatus(tr("FINDING PRESERVED · NARIN ELEVATED TO ACTIVE SCRUTINY","เก็บข้อสรุปแล้ว · ยกระดับ NARIN เป็นบุคคลที่ต้องตรวจเชิงรุก"),"success");setTimeout(()=>{closeRecon();startDialogue(postMatchLines(),()=>{const b=$("#"+WORK+"Action");if(b){b.hidden=false;b.textContent=tr("OPEN SECURE CONTACT","เปิดการติดต่อแบบ Secure")};save("ch5_p2_narin_contact_ready")})},480)
