 document.addEventListener("click",event=>{if(!isP2())return;const d=event.target.closest?.(".ch5-p2-dialogue");if(d){event.preventDefault();advanceDialogue();return}if(event.target.closest?.(".ch5-p2-save")){event.preventDefault();try{window.LastWitnessSaveManager?.open?.("save")}catch(_){}return}if(event.target.closest?.(".ch5-p2-menu")){event.preventDefault();$("#drawer")?.classList.toggle("open");return}if(event.target.closest?.("#restart")){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();$("#drawer")?.classList.remove("open");startFreshForDev();return}},true);
